      ctx.fillStyle = '#18271a'; for (let x = 0; x < w; x += 16) { const p = (x + Math.floor(tick / 3) % 16) % w; ctx.fillRect(p, floor + 7, 8, 2); }
      ctx.fillStyle = '#18271a'; ctx.fillRect(0, floor, w, 2);
