      sad: ['.....', '.###.', '#...#', '#...#', '#.#.#', '.#.#.', '..#..'],
      angry: ['#...#', '.###.', '#...#', '.#.#.', '#...#', '.###.', '.....'],
      shy: ['.....', '.###.', '#...#', '#.#.#', '#...#', '.###.', '..#..']
